package ultra.downloads;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.app.*;import android.widget.*;import android.view.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28)
public class LibraryViewCleanTest {
 Activity c;@Before public void setup(){c=Robolectric.buildActivity(Activity.class).setup().get();LibraryViewClean.restoreAll();}
 LinearLayout row(String title,String count){LinearLayout row=new LinearLayout(c);row.setLayoutParams(new android.widget.AbsListView.LayoutParams(-1,72));row.setMinimumHeight(48);TextView a=new TextView(c),b=new TextView(c);a.setText(title);b.setText("Owner • "+count+" tracks");row.addView(a);row.addView(b);return row;}
 @Test public void aliasRowsAreHiddenAtAnyCountAndRecycledViewsRestore(){LinearLayout a=row("Liked Songs","0"),b=row("Liked Music","5"),d=row("Other","0"),e=row("Liked Songs Forever","10");LibraryViewClean.row(a);LibraryViewClean.row(b);LibraryViewClean.row(d);LibraryViewClean.row(e);assertEquals(View.GONE,a.getVisibility());assertEquals(0,a.getLayoutParams().height);assertEquals(View.VISIBLE,b.getVisibility());assertEquals(View.VISIBLE,d.getVisibility());assertEquals(View.VISIBLE,e.getVisibility());((TextView)a.getChildAt(0)).setText("Real playlist");LibraryViewClean.row(a);assertEquals(View.VISIBLE,a.getVisibility());assertEquals(72,a.getLayoutParams().height);assertEquals(48,a.getMinimumHeight());}
 @Test public void obfuscatedRecyclerUsesItsAccessibilityRole(){LinearLayout list=new LinearLayout(c){@Override public CharSequence getAccessibilityClassName(){return "android.support.v7.widget.RecyclerView";}};LinearLayout empty=row("Liked Songs","0"),real=row("Liked Music","5");list.addView(empty);list.addView(real);LibraryViewClean.apply(list);assertEquals(View.GONE,empty.getVisibility());assertEquals(View.VISIBLE,real.getVisibility());}
 @Test public void leavingRestoresNativeLayout(){LinearLayout a=row("Liked Songs","0");LibraryViewClean.row(a);LibraryViewClean.restoreAll();assertEquals(72,a.getLayoutParams().height);assertEquals(View.VISIBLE,a.getVisibility());}
 @Test public void nestedNativeListsFilterIndividualRowsNotWholeSections(){ultra.test.RecyclerView outer=new ultra.test.RecyclerView(c),inner=new ultra.test.RecyclerView(c);FrameLayout section=new FrameLayout(c);outer.addView(section);section.addView(inner);LinearLayout empty=row("Liked Songs","0"),real=row("Liked Music","5");inner.addView(empty);inner.addView(real);LibraryViewClean.apply(outer);assertEquals(View.VISIBLE,section.getVisibility());assertEquals(View.VISIBLE,inner.getVisibility());assertEquals(View.GONE,empty.getVisibility());assertEquals(View.VISIBLE,real.getVisibility());}
 @Test public void fiveTrackAliasIsMergedNotLeftAsJunk(){LinearLayout alias=row("Liked Songs","5");LibraryViewClean.row(alias);assertEquals(View.GONE,alias.getVisibility());}
 @Test public void headingsAndSimilarNamesStay(){assertFalse(LibraryViewClean.empty(java.util.Arrays.asList("Liked Songs")));assertFalse(LibraryViewClean.empty(java.util.Arrays.asList("Liked Songs Forever","5 tracks")));assertFalse(LibraryViewClean.empty(java.util.Arrays.asList("Liked Music","24 tracks")));assertTrue(LibraryViewClean.empty(java.util.Arrays.asList("Liked Songs, Owner, 5 tracks")));}
}
